import React, { useState, useEffect, useContext } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { AppContext } from '../context/AppContext';
import api from '../utils/api';

const BookDetailsPage = () => {
  const { id } = useParams();
  const [book, setBook] = useState(null);
  const [loading, setLoading] = useState(true);
  const [quantity, setQuantity] = useState(1);
  const { user, buyBook } = useContext(AppContext);
  const navigate = useNavigate();

  useEffect(() => {
    fetchBook();
  }, [id]);

  const fetchBook = async () => {
    try {
      const res = await api.get(`/books/${id}`);
      setBook(res.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleBuy = async () => {
    if (!user) {
      alert('Please login to buy books');
      navigate('/login');
      return;
    }
    const totalAmount = book.price * quantity;
    const confirmMsg = `Confirm Purchase?\n\nBook: ${book.title}\nQuantity: ${quantity}\nPrice per book: ₹${book.price}\nTotal Amount: ₹${totalAmount}\n\nClick OK to confirm`;

    if (window.confirm(confirmMsg)) {
      const success = await buyBook(book._id, quantity);
      if (success) {
        alert(`Order Confirmed!\n\nTotal Amount: ₹${totalAmount}\nQuantity: ${quantity} books`);
        navigate('/orders');
      }
    }
  };

  if (loading) return <p className="text-center text-xl py-12">Loading...</p>;
  if (!book) return <p className="text-center text-xl py-12">Book not found</p>;

  return (
    <div className="max-w-4xl mx-auto mt-12 px-4">
      <div className="bg-white p-8 rounded-lg shadow-lg">
        <img src={book.image} alt={book.title} className="w-full h-96 object-cover rounded-lg mb-6" />
        <h1 className="text-4xl font-bold mb-2 text-gray-800">{book.title}</h1>
        <p className="text-xl text-gray-600 mb-4">by {book.author}</p>
        <p className="text-3xl font-bold text-green-600 mb-4">₹{book.price} per book</p>
        {book.category && <p className="text-gray-700 mb-4"><span className="font-semibold">Category:</span> {book.category}</p>}
        <p className="text-lg leading-relaxed text-gray-700 mb-6">{book.description}</p>

        <div className="bg-gray-50 p-6 rounded-lg mb-6">
          <label className="block text-lg font-semibold mb-3 text-gray-700">Select Quantity:</label>
          <div className="flex items-center gap-4 mb-4">
            <button onClick={() => setQuantity(Math.max(1, quantity - 1))} className="px-4 py-2 bg-gray-300 hover:bg-gray-400 rounded-lg text-xl font-bold">-</button>
            <input type="number" value={quantity} onChange={(e) => setQuantity(Math.max(1, parseInt(e.target.value) || 1))} className="w-20 text-center text-2xl font-bold border-2 border-gray-300 rounded-lg p-2" min="1" />
            <button onClick={() => setQuantity(quantity + 1)} className="px-4 py-2 bg-gray-300 hover:bg-gray-400 rounded-lg text-xl font-bold">+</button>
          </div>
          <div className="text-2xl font-bold text-gray-800">
            Total Amount: <span className="text-green-600">₹{book.price * quantity}</span>
          </div>
        </div>

        <button onClick={handleBuy} className="w-full px-8 py-4 bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-600 hover:to-emerald-700 text-white rounded-lg text-xl font-semibold transition-all shadow-lg hover:shadow-xl">
          Buy Now - ₹{book.price * quantity}
        </button>
      </div>
    </div>
  );
};

export default BookDetailsPage;
